const app = document.querySelector('#app');
const one = (sel) => app.querySelectorAll(sel).length === 1;
assert(one('h1') && app.querySelector('header h1'), 'Put exactly one <h1>, inside <header>.');
assert(app.querySelectorAll('header nav a[href]').length >= 2, 'The <header> needs a <nav> with at least two <a href> links.');
assert(one('main') && app.querySelector('main section h2'), 'Use one <main> containing a <section> with an <h2>.');
assert(app.querySelector('main table caption'), 'The table needs a <caption>.');
assert(app.querySelectorAll('thead th[scope="col"]').length === 3, 'Use three <th scope="col"> cells in <thead>.');
assert(app.querySelectorAll('tbody tr').length === 3, 'The <tbody> should have the three client rows.');
assert(/192\.168\.1\.60/.test(app.querySelector('tbody').textContent), 'Keep the client data (nas 192.168.1.60) in the table.');
const t = app.querySelector('footer time');
assert(t && t.getAttribute('datetime') === '2026-10-05T10:00:00Z', 'Put <time datetime="2026-10-05T10:00:00Z"> inside the <footer>.');
assert(!app.querySelector('.row, .big'), 'Remove the old div rows.');

const form = document.querySelector('#app form');
assert(form, 'Put a <form> in the template.');
assert((form.getAttribute('method') || '').toLowerCase() === 'post' && form.getAttribute('action') === '/api/echo', 'The form needs method="post" and action="/api/echo".');
const f = (n) => form.querySelector(`[name="${n}"]`);
for (const n of ['name', 'ip', 'type', 'port']) assert(f(n), `Add a control with name="${n}".`);
for (const el of form.querySelectorAll('input, select, textarea')) assert(el.labels.length > 0, `The control ${el.name || el.outerHTML} has no <label>.`);
assert(f('type').tagName === 'SELECT' && [...f('type').options].map((o) => o.value).includes('server') && [...f('type').options].map((o) => o.value).includes('printer'), 'type must be a <select> with the options server and printer.');
assert(f('port').type === 'number', 'port must be type="number".');
assert(form.querySelector('button[type="submit"], button:not([type]), input[type="submit"]'), 'Add a submit button.');
f('name').value = ''; f('ip').value = '192.168.1.61'; f('port').value = '80';
assert(!form.checkValidity(), 'An empty name must make the form invalid (required).');
f('name').value = 'nas2';
assert(form.checkValidity(), 'name=nas2, ip=192.168.1.61, port=80 should be valid. Check the pattern (double the backslashes inside the template literal).');
f('ip').value = '192.168.1';
assert(f('ip').validity.patternMismatch, 'ip=192.168.1 should fail the pattern.');
f('ip').value = '192.168.1.61'; f('port').value = '70000';
assert(f('port').validity.rangeOverflow, 'port=70000 should be out of range (max="65535").');

