const app = document.querySelector('#app');
const bs = app.querySelectorAll('b');
assert(bs.length === 1 && bs[0].parentElement.tagName === 'P' && bs[0].textContent === 'online', 'There should be exactly one <b>online</b>, inside the Status paragraph (got ' + bs.length + ' <b> elements).');
const ps = [...app.querySelectorAll('p')];
assert(ps.every((p) => p.textContent.trim() !== ''), 'Remove the empty paragraph the parser created from the stray </p>.');
assert(ps.length === 3, 'Expected exactly 3 paragraphs, found ' + ps.length + '.');
const ul = app.querySelector('ul');
assert(ul && ul.parentElement === app && ul.children.length === 3, 'The <ul> with three <li> should be a direct child of #app.');
assert(!app.querySelector('b ul, b p, b h2'), 'The bold text must not wrap other blocks.');
